(() => {
 'use strict';
 const data=window.MORIYATI_NEWSLETTER,root=document.getElementById('newsletter-article');
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let current=data.editions[0];
 function render(){
  const lang=window.MoriyatiLocale.language,c=current[lang],fa=lang==='fa',n=new Intl.NumberFormat(lang),num=(v,d=2)=>new Intl.NumberFormat(lang,{maximumFractionDigits:d,minimumFractionDigits:d}).format(v);
  const refs=new Map(current.sources.map((s,i)=>[s.id,i+1]));
  const label=current.edition==='morning'?(fa?'شمارهٔ صبح':'Morning edition'):(fa?'شمارهٔ شب':'Evening edition');
  const date=fa?current.dateFa:new Intl.DateTimeFormat('en',{dateStyle:'long',timeZone:'UTC'}).format(new Date(current.date+'T12:00:00Z'));
  const time=fa?current.time.replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]):current.time;
  const ref=id=>'<a class="rate-source" href="#news-source-'+esc(id)+'" aria-label="'+(fa?'منبع ':'Source ')+n.format(refs.get(id))+'">['+n.format(refs.get(id))+']</a>';
  const hero='<header class="news-cover" data-cover-edition="'+current.edition+'"><img src="'+current.cover+'" width="1672" height="941" alt="'+esc(current.coverAlt[lang])+'"><div class="news-cover-type"><span lang="en" dir="ltr">MORIYATI</span><p>'+label+'</p><time datetime="'+current.date+'T'+current.time+':00+03:30">'+esc(date)+'</time><strong dir="ltr">'+time+'</strong><small>'+(fa?'به وقت تهران':'Tehran time')+'</small></div></header>';
  const cards='<div class="market-pulse">'+current.globalSnapshot.map(x=>'<article class="pulse-card"><span class="pulse-symbol" lang="en">'+x.symbol+'</span><div class="pulse-label">'+x.label[lang]+'</div><strong class="pulse-value" dir="ltr">'+(fa?num(x.value):'$'+num(x.value))+'</strong><p class="pulse-unit">'+x.unit[lang]+'</p><div class="pulse-change">'+(x.change>0?'<span class="rate-up">'+(fa?'رشد':'Up')+' ('+num(x.change,1)+(fa?'٪':'%')+')</span>':fa?'بدون تغییر':'Unchanged')+' <span>'+(fa?'تغییر روزانه':'Daily change')+'</span></div><small>'+x.observedAt+' · '+(fa?'تهران':'Tehran')+' '+ref(x.sourceId)+'</small></article>').join('')+'</div><div class="gold-silver-ratio"><span>'+(fa?'نسبت طلا به نقره':'Gold / silver ratio')+'</span><strong dir="ltr">'+num(current.ratio)+'</strong><span>'+(fa?'بر پایهٔ دو نرخ هم‌زمان این شماره':'Based on this edition’s simultaneous observations')+'</span></div>';
  const table='<div class="domestic-table-wrap"><table class="domestic-rates"><caption>'+esc(current.iranSnapshotNote[lang])+'</caption><thead><tr><th>'+(fa?'بازار':'Market')+'</th><th>'+(fa?'نرخ و مبنا':'Rate & basis')+'</th><th>'+(fa?'زمان ثبت':'Observed')+'</th></tr></thead><tbody>'+current.iranSnapshot.map(x=>'<tr><th scope="row">'+x.label[lang]+'</th><td><strong>'+x.value[lang]+'</strong><span>'+x.unit[lang]+'</span></td><td>'+x.observedAt[lang]+' '+ref(x.sourceId)+'</td></tr>').join('')+'</tbody></table></div>';
  const stories=key=>c[key].map(story=>'<article class="news-story'+(story.type==='editorial'?' news-analysis':'')+'">'+(story.type==='editorial'?'<span class="news-story-kind">'+(fa?'نگاه تحلیلی خانه':'The House’s analytical view')+'</span>':'')+'<h3>'+esc(story.heading)+'</h3>'+story.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join('')+(story.sourceIds.length?'<div class="news-story-refs">'+(fa?'منابع ':'Sources ')+story.sourceIds.map(ref).join('')+'</div>':'')+'</article>').join('');
  const outlook=current.outlook[lang];
  const session='<aside class="session-outlook"><span class="eyebrow">'+(fa?'چشم‌انداز پنج‌جلسه‌ای در زمان انتشار':'Five-session outlook at publication')+'</span><div><p><span>'+(fa?'طلا':'Gold')+'</span><strong>'+outlook.gold+'</strong><small>'+outlook.confidenceGold+'</small></p><p><span>'+(fa?'نقره':'Silver')+'</span><strong>'+outlook.silver+'</strong><small>'+outlook.confidenceSilver+'</small></p></div></aside>';
  const comparison=current.edition==='evening'?'<figure class="market-comparison"><figcaption><h3>'+(fa?'از صبح تا شب':'Morning to evening')+'</h3><span>'+(fa?'مقایسهٔ دو ثبت آرشیوی در یک روز':'Two archived observations from the same day')+'</span></figcaption>'+[['gold',fa?'طلا':'Gold'],['silver',fa?'نقره':'Silver']].map(([key,title])=>{const a=current.comparison.morning[key],b=current.comparison.evening[key],change=(b/a-1)*100;return '<div class="comparison-row"><strong>'+title+'</strong><div dir="ltr"><span>'+num(a)+'</span><svg viewBox="0 0 250 56" aria-hidden="true"><path d="M12 12L238 43"/><circle cx="12" cy="12" r="3"/><circle cx="238" cy="43" r="3"/></svg><span>'+num(b)+'</span></div><small>'+(fa?'افت':'Down')+' ('+num(Math.abs(change))+(fa?'٪':'%')+')</small></div>';}).join('')+'<div class="comparison-times" dir="ltr"><span>06:46 · Tehran</span><span>22:35 · Tehran</span></div></figure>':'';
  root.innerHTML=hero+'<div class="news-title-block"><span class="eyebrow">'+(fa?'شمارهٔ ':'Issue ')+n.format(data.editions.indexOf(current)+1)+' / '+(fa?'آرشیو خبرنامه':'Newsletter archive')+'</span><h2>'+esc(c.title)+'</h2><p class="newsletter-summary">'+esc(c.summary)+'</p><nav class="bulletin-section-links" aria-label="'+(fa?'بخش‌های خبرنامه':'Newsletter sections')+'"><a href="#global">'+(fa?'بازار جهانی':'Global markets')+'</a><a href="#iran">'+(fa?'بازار ایران':'Iranian markets')+'</a></nav></div><div class="newsletter-report"><section id="global" class="newsletter-column"><div class="newsletter-column-head"><span lang="en">01</span><h2>'+(fa?'بازار جهانی':'Global markets')+'</h2></div>'+cards+comparison+stories('global')+session+'</section><section id="iran" class="newsletter-column"><div class="newsletter-column-head"><span lang="en">02</span><h2>'+(fa?'بازار ایران':'Iranian markets')+'</h2></div><p class="iran-market-deck">'+(fa?'طلا، نقره، بورس و ارز':'Gold, silver, equities & currencies')+'</p>'+table+stories('iran')+'</section></div><section class="newsletter-sources"><h2>'+(fa?'منابع این شماره':'Sources for this edition')+'</h2><ol>'+current.sources.map(s=>'<li id="news-source-'+esc(s.id)+'"><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer" dir="auto">'+esc(s.title)+'</a></li>').join('')+'</ol><p class="news-report-footer">'+(fa?'گزارش آرشیوی موریاتی؛ بدون توصیه یا اجرای معامله.':'Moriyati archive report; no trading recommendation or execution.')+'</p></section>';
  document.querySelectorAll('[data-edition]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.edition===current.edition)));
  document.querySelectorAll('[data-news-id]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.newsId===current.id)));
  document.querySelector('.bulletin-editorial').dataset.edition=current.edition;
 }
 document.querySelectorAll('[data-edition]').forEach(b=>b.addEventListener('click',()=>{current=data.editions.find(e=>e.edition===b.dataset.edition);render();}));
 document.querySelectorAll('[data-news-id]').forEach(b=>b.addEventListener('click',()=>{current=data.editions.find(e=>e.id===b.dataset.newsId);render();document.querySelector('.bulletin-edition-bar').scrollIntoView({behavior:document.documentElement.classList.contains('motion-reduced')?'instant':'smooth',block:'start'});}));
 addEventListener('moriyati:language',render);
 window.MORIYATI_BULLETIN=Object.freeze({mode:'archive',automaticPublication:false,timezone:'Asia/Tehran',slots:['11:00','23:00']});
 render();
})();
